export function translate(value: string, language: Language): string {
  return language === "pl" ? (PL[value] ?? value) : value;
}

export function useI18n() {
  const [language, setLanguage] = useState<Language>(() => loadTheme().language);
  useEffect(() => {
    const update = () => setLanguage(loadTheme().language);
    window.addEventListener("notible:preferences", update);
    return () => window.removeEventListener("notible:preferences", update);
  }, []);
  // Components frequently use `t` as a dependency of data-loading callbacks.
  // A new function on every render makes those effects run forever
  // (loading -> render -> new t -> loading). Keep it stable until the actual
  // language changes.
  const t = useCallback((value: string) => translate(value, language), [language]);
  return { language, locale: calendarLocale(language), t };
}
